def add_populated_list_to_scf(scf_path, dist_name, list_name, list_elements: dict):
    """
    add a list to the scf, overriding if it exists already.
    Note: dist_name does not need to include the MRBTS part,
    as taf.config.scf will find the MRBTS number automatically.
    """
    scf = config_scf()
    scf.load_scf(file_path=scf_path)
    if scf.is_list_in_object(dist_name=dist_name, list_name=list_name):
        scf.remove_list_from_scf(dist_name=dist_name, list_name=list_name)
    scf.add_list_to_scf(dist_name=dist_name, list_name=list_name)
    scf.add_item_to_list(dist_name=dist_name, list_name=list_name, elements=list_elements)
    date_time = datetime.now()
    scf_name = "new_scf_" + date_time.strftime("%Y-%m-%d_%H-%M-%S") + ".xml"
    scf.save_scf(scf_name)
    return scf_name


def integrate_emssim_with_bts(bts_id, host, user, tls=1):
    ems = ta_emss()
    ems.setup_emss(bts_id=bts_id, host=host, port=int(bts_id) + 4000, user=user, ne3s=True,
                   req_user='Nemuadmin', req_password='nemuuser', tls=True,
                   wait_discovered=False, wait_connected=False)
    ems.run_emssim_command('ne3s_activate -password nemuuser -user Nemuadmin -tls {}'.format(tls))
    return ems


def create_connection_if_not_exist(connection, alias):
    if not connection:
        return BuiltIn().run_keyword('st46_keywords.Connect To Admin', 'alias={}'.format(alias))
    return connection


def recommission_parameter(dist_name, param_name, operation, param_value,
                           skip_parameter_relation_errors, should_activate,
                           timeout, retry, connection):
    response = BuiltIn().wait_until_keyword_succeeds('{}x'.format(retry),
                                                     '{}s'.format(30),
                                                     'coam_admin.perform_parameter_recommissioning',
                                                     dist_name,
                                                     param_name,
                                                     operation,
                                                     param_value,
                                                     skip_parameter_relation_errors,
                                                     should_activate,
                                                     timeout,
                                                     connection)

    logger.info('Performed parameter {operation} on BTS ({dist_name}/{param_name}), {param_value}'
                .format(operation=operation,
                        dist_name=dist_name,
                        param_name=param_name,
                        param_value=param_value), also_console=True)
    return response


def recommission_object(dist_name, operation, skip_parameter_relation_errors,
                        should_activate, timeout, retry, connection, **kwargs):
    parameter_list = create_multiple_parameters_recommission_list(kwargs)

    response = BuiltIn().wait_until_keyword_succeeds('{}x'.format(retry),
                                                     '{}s'.format(30),
                                                     'coam_admin.perform_object_recommissioning',
                                                     dist_name,
                                                     parameter_list,
                                                     operation,
                                                     skip_parameter_relation_errors,
                                                     should_activate,
                                                     timeout,
                                                     connection)

    summary = create_additional_parameter_list(kwargs)
    logger.info('Performed parameters {operation} on BTS ({param_summary})'
                .format(operation=operation, param_summary=summary), also_console=True)

    return response


def create_additional_parameter_list(params_dict):
    str_dict = ['{}: {}'.format(key, value) for key, value in params_dict.items()]
    return ', '.join(str_dict)


def close_connection_with_emssim(bts_id, connection):
    logger.console('Close connection with EMSSIM')
    connection.teardown_emss(bts_id=bts_id)


def create_multiple_parameters_recommission_list(params_dict):
    return [{
        'parameterName': param_name,
        'operation': 'update',
        'value': param_value
    } for param_name, param_value in params_dict.items()]


def generate_binary_file(hex_string_file_name, binary_file_name):
    with open(hex_string_file_name, 'r') as f:
        hex_string = f.read()

    binary_data = unhexlify(hex_string)

    with open(binary_file_name, 'wb') as f:
        f.write(binary_data)


def execute_command_on_emssim(command, connection):
    logger.console('Execute command on EMSSIM: {}'.format(command))
    try:
        connection.run_emssim_command(command)
        logger.console('Command executed')
    except Exception as e:
        logger.console('Error msg: {}'.format(e))
        raise


def sequence_list_for_cipher_selection(sublist, orderlist):
    x = ''.join([repr(d) for d in orderlist]).replace("'", "")
    y = ''.join([repr(d) for d in sublist]).replace("'", "")
    return y in x


def delete_structure_from_scf(base_scf_path, scf_dist_name, scf_list_name):
    config_scf.load_scf(file_path=base_scf_path)
    config_scf.remove_list_from_scf(dist_name=scf_dist_name, list_name=scf_list_name)
    config_scf.save_scf("new_scf.xml")
    return "new_scf.xml"


def extract_ims2(snapshot_path):
    path = os.path.splitext(snapshot_path)[0]
    with zipfile.ZipFile(snapshot_path, 'r') as zf:
        zf.extractall(path)
    for f in glob.glob("{}/*".format(path)):
        if f.endswith("ims2"):
            os.rename(f, os.path.join(os.path.dirname(path), os.path.basename(f)))
    shutil.rmtree(path)


def get_fingerprint_object_parameters(fingerprint, username):
    params_list = [
        {"parameterName": "certToNameMappingList",
         "operation": "update",
         "value": [{"certFingerPrint": "02:" + fingerprint,
                    "mapType": "specified",
                    "userName": username}]}
    ]
    return params_list


def start_tshark_on_vm(pcap_file, vm_password):
    os.system("echo {} | sudo -S tcpdump -i enp1s0f0 -w {} 2>/dev/null&".format(vm_password, pcap_file))


def stop_tshark_on_vm(vm_password):
    os.system("echo {} | sudo -S pkill tcpdump".format(vm_password))
    sleep(10)


def get_list_of_params_for_mplaneonap_object(bts_id):
    params_list = [{"parameterName": "activateOranO1NetconfService", "operation": "update", "value": "true"},
                   {"parameterName": "mPlaneOnapId", "operation": "update", "value": 1},
                   {"parameterName": "mPlaneAddressDN", "operation": "update",
                    "value": "MRBTS-{}/TNLSVC-1/TNL-1/IPNO-1/IPIF-1/IPADDRESSV4-1".format(bts_id)}]
    return params_list


def get_proper_software_string(soft_to_prepare):
    """
    Takes a software string in Webem format as argument and transforms it to UTE Manager format.
    5G21B_GNB_0012_000400_000971 ->  5G21B_12.400.971
    :param: soft_to_prepare: string with software version in Webem format
    :return: string with software version in UTE Manager format
    """

    def get_stream_number(string):
        """
        Takes a string of digits and delets all zeroes from the left side till first non zero number.
        Outcome of each argument for this function will be placed in to a software list later.
        [5G22R1, GNB, 0000, 000400, 002632] -> [5G22R1, GNB, 0, 400, 2632]
        """
        for digit in range(len(string)):
            if string[digit] != '0':
                return string[digit:]
        return "0"

    soft_list = soft_to_prepare.split('_')
    soft_list = [get_stream_number(el) for el in soft_list]
    soft_to_download = ''

    if check_if_bts_software_is_cloud(soft_to_prepare):
        if check_if_bts_software_is_trunk(soft_to_prepare):
            soft_to_download += ('5G_' + soft_list[2] + '.' + soft_list[3] + '.' + soft_list[4])
        else:
            soft_to_download += (soft_list[0] + '_' + soft_list[2] + '.' + soft_list[3] + '.' + soft_list[4])
    else:
        if check_if_bts_software_is_trunk(soft_to_prepare):
            if 'ENB_999' in soft_to_prepare:
                soft_to_download = 'SBTS00' + soft_to_prepare[soft_to_prepare.index('_'):]
            else:
                soft_to_download = soft_list[0] + soft_to_prepare[soft_to_prepare.index('_'):]
        else:
            soft_to_download = soft_to_prepare
    return soft_to_download


def check_if_bts_software_is_cloud(soft_version):
    """
    From SBTS release, Classical soft has SBTS version, but Classical 21A and Classical 20B
    has not SBTS, so we should process those two soft versions differently. Two classical
    softs: 5G21A_GNB, 5G20B_GNB in UTE Manager look like cloud softs, that's why at the
    beggining it chcecks those two first, so it won't treat them as cloud ones.
    """
    if "5G21A_GNB" in soft_version or "5G20B_GNB" in soft_version:
        return False
    return True if "GNB" in soft_version else False


def check_if_bts_software_is_trunk(soft_version):
    return True if ("ENB_9999" in soft_version or "GNB_0000" in soft_version) else False


def check_if_is_sw_is_downloaded(soft_to_check):
    soft_file_name = get_software_pack_name(soft_to_check)
    list_of_files = [str(wanted_file) for path in possible_paths_with_soft
                     for wanted_file in Path(path).glob(soft_file_name + "/" + soft_file_name + "*")]
    if len(list_of_files) > 0:
        return True, list_of_files[0]
    return False, None


def get_software_pack_name(soft_name):
    if soft_name.count('_') > 1:
        specified_sw_pack_name = soft_name
    else:
        specified_sw_pack_name = soft_name[soft_name.index('_') + 1:]
    return specified_sw_pack_name


def get_downloadable_software_link(soft_version):
    """
    Takes string with software version as shown in UTE Manager, then, according to this string (cloud or classical),
    prepares appropriate link to remote repository which contains downloadable package with that software.
    :param: soft_version: string with software version in UTE Manager format.
    :return: link to downloadable package with software and name of downloaded software packet.
    """
    if soft_version.count('_') > 1:
        head_ute = "http://files.ute.nsn-rdnet.net/builds/enb/base/"
        tail_link_ute = soft_version + '/' + soft_version + '_release_BTSSM_downloadable.zip'
        head_wft = "https://lterel.es-si-s3-z4.eecloud.nsn-net.net/build/"
        tail_link_wft = soft_version[:soft_version.index('_')] + '/' + soft_version + '_release_BTSSM_' \
                                                                                      'downloadable_A54.zip'
        wft_time = requests.get("http://lterel.es-si-s3-z4.eecloud.nsn-net.net/build/").elapsed.total_seconds()
        ute_time = requests.get("http://files.ute.nsn-rdnet.net/builds/enb/base/").elapsed.total_seconds()
        if ute_time < wft_time:
            try:
                response = urllib.request.urlopen(head_ute + tail_link_ute)
                status_code = response.getcode()
                if 200 >= status_code < 300:
                    head = head_ute
                    tail_link = tail_link_ute
                else:
                    head = head_wft
                    tail_link = tail_link_wft
            except Exception:
                head = head_wft
                tail_link = tail_link_wft
        else:
            head = "https://lterel.es-si-s3-z4.eecloud.nsn-net.net/build/"
            tail_link = soft_version[:soft_version.index('_')] + '/' + soft_version + '_release_BTSSM_' \
                                                                                      'downloadable_A54.zip'
    else:
        head = "https://artifactory-espoo1.ext.net.nokia.com/artifactory/mnp5g-central-public-local/System_Release/"
        tail_link = soft_version[soft_version.index('_') + 1:] + '/AirScale-'\
            + soft_version[soft_version.index('_') + 1:] + '.zip'
    logger.console("link to download software:")
    logger.console(head + tail_link)
    return head + tail_link


def download_software(downloadable_link, directory):
    """
    Runs a command in the terminal to start downloading sw package.
    :param: downloadable_link: link to downloadable package with software.
    :param: directory: place to store package in.
    :return: path to downloaded soft
    """
    download_sw_command = "wget " + downloadable_link + " -P {dir}".format(dir=directory)
    os.system(download_sw_command)
    path_to_sw = directory + downloadable_link[downloadable_link.rfind('/'):]
    assert os.path.exists(path_to_sw)
    assert os.path.getsize(path_to_sw) > 0
    return path_to_sw


def login_via_webem_with_ldap_credentials(address, login, password, parameter):
    options = Options()
    options.add_argument('ignore-certificate-errors')
    options.add_argument('--headless')
    options.add_argument('--no-sandbox')
    options.add_argument('--disable-dev-shm-usage')
    options.add_experimental_option("detach", True)
    browser = webdriver.Chrome(chrome_options=options)
    browser.get(address)
    time.sleep(1)
    log = browser.find_element_by_xpath('//input[@placeholder="Username"]')
    log.send_keys(login)
    pas = browser.find_element_by_xpath('//input[@type="password"]')
    pas.send_keys(password)
    browser.find_element_by_xpath('//button[@type="button" and contains(., "Login")]').click()
    WebDriverWait(browser, 60).until(EC.presence_of_element_located((By.XPATH, '//button[@type="button" '
                                                                               'and contains(., "Confirm")]'))).click()
    time.sleep(10)
    address_to_commissioning = address + "/#/configuration/parameters-editor"
    browser.get(address_to_commissioning)
    time.sleep(5)
    param = browser.find_element_by_xpath('//input[@placeholder="Search all"]')
    param.send_keys(parameter)
    param.send_keys(Keys.ENTER)
    browser.find_element_by_xpath('//button[@ui-tooltip="Delete parameter"]').click()
    browser.find_element_by_xpath('//button[@ui-tooltip="Validate Plan"]').click()
    time.sleep(5)
    browser.find_element_by_xpath('//button[@ui-tooltip="Activate Plan"]').click()
    WebDriverWait(browser, 60).until(EC.presence_of_element_located((By.XPATH, '//button[@type="button" '
                                                                               'and contains(., "Execute")]'))).click()
    WebDriverWait(browser, 120).until(EC.element_to_be_clickable((By.XPATH, '//button[@type="button" '
                                                                            'and contains(., "Close")]'))).click()
    browser.close()
    return browser
